    description: "Dr. Ajmeera Kiran working as Associate Professor and Head , Computer Science and Engineering Department at MLR Institute of Technology, Hyderabad, Telangana, India.  He received the B.E degree in Computer Science and Engineering from Vasavi College of Engineering affiliated to Osmania University, Hyderabad in 2012. In 2014, received the MTech degree in Computer Science and Engineering from Jawaharlal Nehru Technological University, Hyderabad. In 2021, received the Ph.D. degree in Faculty of Computer Science & Engineering from JNTUH, Hyderabad, Telangana, India. He has 5 years experience in teaching and 6.5 years in research, he published around 200 publications in International/National journals and conferences include 20 SCI papers. 15 Patents in data mining and big data analytics. He also authored 6 books / books chapters by various international publishers. He was also a convener for various FDP's, coordinator for Student workshop's, Hackathon's. He is a life member of professional bodies like Indian Society for Technical Education (LMISTE), Computer society of India (CSI), Member in IEEE.  Research interest includes Information Security, Network Security, Big data Analytics and Machine Learning, Artificial Intelligence, Data Mining, Internet of Thing's.",
