    description: "A. Sangeetha is an Assistant Professor in the Department of Computer Science and Engineering at MLR Institute of Technology. She possesses extensive experience in teaching, research, and student mentoring. Her areas of expertise include Artificial Intelligence, Machine Learning, Deep Learning, Internet of Things (IoT), Computer Vision, and Data Analytics. She is deeply committed to motivating students to achieve their career goals by providing academic guidance, fostering technical skills, and encouraging continuous learning and professional development.\n\nA dedicated lifelong learner, she has successfully completed numerous NPTEL certification courses in emerging technologies and has been honored with prestigious recognitions such as NPTEL Star, NPTEL Domain Star, and NPTEL Motivated Learner for her outstanding commitment to learning and student engagement. She has published research papers in reputed journals and conferences and has contributed to innovation through multiple Indian patent applications in areas including smart systems, healthcare technologies, and intelligent computing. Her passion for excellence in teaching, research, and mentorship continues to inspire students and contribute significantly to the academic community.",
