    description: "Mr. Bolleddu Devananda Rao is an Associate Professor in the Department of Computer Science and Engineering at MLR Institute of Technology, Hyderabad. He is currently pursuing a Ph.D. in the Faculty of Computer Science and Engineering at Jawaharlal Nehru Technological University Anantapur. His research interests include Artificial Intelligence, Machine Learning, Deep Learning, Medical Image Processing, and Healthcare Analytics. His ongoing research primarily focuses on AI-driven cancer detection systems using hybrid deep learning approaches for improved diagnostic accuracy. He has actively contributed to research in medical imaging and intelligent healthcare systems, particularly in bone and lung cancer detection using CNN- and fusion-based models. In addition to research, he is involved in teaching undergraduate engineering students and guiding academic projects in emerging technologies related to AI and data science.",
