    description: "E.N. Vijaya Kumari is an Assistant Professor in the Department of Computer Science and Engineering at MLR Institute of Technology (MLRIT) with approximately eight years of teaching experience. She is dedicated to delivering high-quality, student-centered education. Her areas of interest include Machine Learning, Data Science, and Database Management Systems. She is passionate about applying advanced computational techniques to solve real-world problems, particularly in the healthcare domain.\n\nShe emphasizes concept-driven learning and encourages students to develop analytical thinking and practical problem-solving skills. She is actively involved in academic and research activities and continuously works on enhancing her teaching methodologies. Her goal is to contribute to innovative research and foster academic excellence among students in the field of computer science.",
