    description: "Dr. K. Pushpa Rani is an accomplished academician and researcher with over 21 years of teaching and research experience in the field of Computer Science and Engineering. She currently serves as an Associate Professor and has made significant contributions in the domains of Natural Language Processing (NLP), Machine Learning, Deep Learning, Internet of Things (IoT), and Intelligent Systems.\n\nShe holds a Ph.D. in Computer Science and Engineering with specialization in Natural Language Processing (NLP), focusing on advanced computational techniques for intelligent language understanding, information retrieval, and automated decision-making systems.\n\nDr. K. Pushpa Rani has an extensive research portfolio with numerous publications in reputed international journals, IEEE conferences, Springer journals, and Scopus-indexed venues, covering areas such as healthcare analytics, smart systems, cloud security, deep learning applications, and NLP-based intelligent frameworks. She has also contributed significantly to emerging areas like topic modeling, sentiment analysis, RAG-based systems, and AI-driven predictive modeling.\n\nShe actively serves the academic community as a reviewer for various international journals and conferences, contributing to the quality enhancement of scholarly publications in AI and computing domains.\n\nIn addition to her research contributions, she holds important academic leadership roles:\n\nEditorial Board Member of International Journal of Intelligent Knowledge Processing Systems (IJIKPS)\nCo-Guide for Ph.D. scholars guiding advanced research in AI and NLP\nChairman for Research Scholars at SR University, supporting doctoral research activities and academic development\n\nHer academic contributions also include patents, books, and innovative system designs in areas such as IoT-based healthcare systems, smart security frameworks, and deep learning applications for real-world problem solving.\n\nDr. Pushpa Rani is widely recognized for her dedication to research mentorship, academic leadership, and innovation-driven teaching methodologies, and continues to contribute actively to the advancement of intelligent computing systems and research excellence in higher education.",
