    description: "Mr. Nagarjuna Tandra is an Associate Professor in the Computer Science and Engineering Department at MLR Institute of Technology, Telangana, Hyderabad. With a strong academic foundation and extensive industry experience, he brings a unique perspective to his teaching and research.\n\nMr. Tandra completed his Bachelor's degree in Computer Science and Engineering from JNT University, Kakinada, in 2008. He further enhanced his expertise by earning three master's degrees: Software Engineering from GITAM University, Visakhapatnam (2012); Computer Science and Engineering from North Western Polytechnic University, California, USA (2016); and Information Technology Management from Campbellsville University, Kentucky, USA (2019).\n\nWith 3 years of teaching experience and 10 years in the IT industry, Mr. Tandra combines practical insights with academic rigor. He has published around 20 research articles in national and international journals and conferences. His research interests include Information Security, Network Security, Big Data Analytics, Machine Learning, Artificial Intelligence, Data Mining, and the Internet of Things.\n\nOutside of academia, Mr. Tandra is passionate about applying emerging technologies to solve real-world problems and mentoring the next generation of engineers and researchers.",
