    description: "Palelli Purushotham is an Assistant Professor in the Department of Computer Science and Engineering at MLR Institute of Technology, Hyderabad. With over 10 years of teaching and research experience, he specializes in programming, network security, and machine learning. He holds a B.Tech and M.Tech in Computer Science and is currently pursuing his Ph.D. at NIT Warangal. His contributions include journal publications, international conference papers, patents, and books, reflecting his commitment to advancing research in healthcare, smart cities, assistive technologies, and AI applications.",
