    description: "Thrimurthulu Vobbilineni, He is currently working Professor, Department of Computer Science and Engineering, MLR Institute of Technology, Dundigal, Hyderabad, Telangana, India. \nHis research interests include wireless Communication, IoT, Embedded systems, VLSI and soft computing application in AI & machine learning.\nDr. V. Thrimurthulu is a distinguished professor and academician specializing in Electronics and Communication Engineering (ECE) and Computer Science Engineering (CSE), with over 28 years of combined experience in teaching, research, and industry. He currently serves as a Professor in the Department of Computer Science and Engineering (CSE) at the MLR Institute of Technology (MLRIT) in Hyderabad, India, joining in January 2024. \nAcademic and Research Background:Education: Dr. Thrimurthulu holds a Doctorate (Ph.D.) in ECE (Wireless Cellular Communication) from a Central University (2012). He completed his M.E. in Microwaves and Radar Engineering from Osmania University (2003) and his graduation (AMIETE) from the Institute of Electronics & Telecommunication Engineering, New Delhi (1994).\nResearch Focus: His research interests include Radar Signal Processing, Wireless Cellular Communication, Internet of Things (IoT), Digital Image Processing, and Antenna Design.\nPublications: He has published over 40 technical research papers in national and international journals and conferences.",
