    books: [],
    description: "Vineesha Mamillapalli is an Assistant Professor in the Department of Computer Science and Engineering at MLR Institute of Technology. She holds an M.Tech degree and has a total of 9 years of teaching experience, including 2 years and 4 months at MLR Institute of Technology. Her teaching interests include Artificial Intelligence, Machine Learning, Deep Learning, Natural Language Processing, Software Engineering, Cloud Computing, DevOps, and other emerging technologies.\n\nShe is passionate about creating an engaging learning environment that fosters critical thinking, problem-solving, and the practical application of computing concepts. Her primary research interest lies in Deep Learning, with a focus on developing intelligent systems and exploring innovative solutions to real-world challenges. She actively participates in academic and professional development activities, mentors student projects, and strives to contribute to excellence in teaching, research, and student development. Through her work, she aims to equip students with both strong theoretical foundations and industry-relevant skills, preparing them for successful careers in the rapidly evolving field of technology.",
