    description: "Mr. Juttu Suresh is a dedicated academician and researcher in the field of Computer Science and Engineering and Information Technology, currently serving as an Assistant Professor in the Department of CSE (Data Science) at MLR Institute of Technology (MLRIT), Dundigal, Telangana. He brings over 10 years of rich teaching experience and academic leadership to the table, having previously held key positions such as Head of Department and Assistant Professor at institutions like Malla Reddy Engineering College and Management Sciences, Adam\'s Engineering College, and KLR College of Engineering and Technology. \nHe has completed his M.Tech and B.Tech from Jawaharlal Nehru Technological University, Hyderabad. His academic interests span across Computer Programming Languages and Artificial Intelligence, Internet of Things, Natural Language Processing, Data Analytics, Advanced Operating Systems, Cryptography, and Cloud Computing. He has published research papers in reputed international journals covering a wide range of emerging areas such as machine learning, cybersecurity, blockchain, medical imaging, and energy-efficient networks. His contributions also include two published patents focused on AI-driven signature verification and multimodal image fusion. \nHe is highly active in professional development, having completed more than 20 Faculty Development Programs (FDPs) on topics such as Generative AI, Deep Learning, Cloud Architecture, AI in Healthcare and Finance, and more. His textbook titled IoT and Big Data stands as a testament to his academic outreach and publishing contributions. \nKnown for his effective organizational skills, clear communication, and passion for innovation, He is continuously strives to bridge theoretical foundations with practical applications in data science and computing. Beyond academics, he enjoys playing cricket and chess, and is an avid learner of emerging technologies.\nEmail: sureshjuttu2024@gmail.com & sureshjuttu@mlrit.ac.in \nORCID :0009-0002-5311-68169\nGoogle Scholar Name: Juttu Suresh",
