    description: "Dr. Sivakrishna Kondaveeti is an Associate Professor in the Department of Computer Science and Engineering (Artificial Intelligence and Machine Learning) at MLR Institute of Technology, Hyderabad, India. He possesses more than 14 years of experience in teaching, research, and academic administration.\n\nHe received his B.Tech degree from JNTU Hyderabad in 2008, M.Tech in Digital Electronics and Communication Systems in 2012, and Ph.D. in Electronics and Communication Engineering from Koneru Lakshmaiah Education Foundation (KLEF), India, in 2022.\nBefore joining MLR Institute of Technology, Dr. Sivakrishna served as an Assistant Professor, Junior Research Fellow, and Senior Research Fellow at KL University and the Space Technology and Atmospheric Research Laboratory (STAR Lab) between 2009 and 2022. He has also worked as a Trainee Software Engineer at Shraddhaa Information Technologies Pvt. Ltd., Hyderabad.His research interests include Global Navigation Satellite Systems (GNSS), ionospheric Total Electron Content (TEC) prediction, space science, machine learning, deep learning, computer vision, biomedical signal processing, and medical image analysis. His work focuses on developing advanced AI and deep learning models for atmospheric science, healthcare applications, and intelligent systems.\nDr. Sivakrishna has published more than 17 research papers in reputed SCI/SCIE/Scopus-indexed journals, including publications with IEEE, Springer, Elsevier, and other leading publishers. He has actively participated in several national and international conferences, workshops, and faculty development programs, including international workshops conducted in Switzerland, Austria, and Japan.\nHe has earned multiple NPTEL certifications in areas such as Machine Learning, Deep Learning, Computer Vision, Natural Language Processing, Reinforcement Learning, Python Programming, and Data Science. In recognition of his continuous learning efforts, he was awarded the NPTEL Believer and NPTEL Enthusiast recognitions.\n\nDr. Sivakrishna has also received copyrights for innovative AI-based prediction models, including deep learning frameworks for forecasting ionospheric Total Electron Content (TEC) and temperature prediction systems. His contributions to research and innovation continue through collaborations, journal publications, conference presentations, and mentoring undergraduate and postgraduate students.\n\nIn 2025, he was selected for a Post-Doctoral position at the Advanced Information & Communication Technology Laboratory, Department of Electronic Engineering, National Kaohsiung University of Science and Technology (NKUST), Taiwan, further strengthening his international research profile.\nHis professional mission is to advance interdisciplinary research that integrates artificial intelligence, machine learning, space science, and healthcare technologies while inspiring students and researchers to pursue innovation-driven solutions for real-world challenges.",
