    description: "Mrs. Badepalli Anusha is an Assistant Professor in the Department of Electronics and Communication Engineering at MLR Institute of Technology, Hyderabad. She holds an M.Tech degree in VLSI System Design from CVR College of Engineering, affiliated with JNTU Hyderabad, and a B.Tech degree in Electronics and Communication Engineering. With over ten years of teaching experience, she has been actively involved in undergraduate teaching, student mentoring, and project guidance. Her areas of interest include VLSI Design, Digital System Design, Communication Systems, Artificial Intelligence applications, and Embedded Systems. She has published research papers in reputed journals and international conferences, with contributions spanning VLSI, IoT, renewable energy integration, intelligent transportation systems, and AI-assisted healthcare prediction. She continuously enhances her academic and research expertise through NPTEL certifications, faculty development programs, workshops, and professional training in emerging technologies.",
