    description: "Dr. Ganesh Miriyala is an Assistant Professor in the Department of Electronics and Communication Engineering and Head of the Center for Innovation and Entrepreneurship (CIE) at MLR Institute of Technology, Hyderabad, India. He obtained his B.Tech. in Electronics and Communication Engineering from JNTUH, M.Tech. in Communication Engineering from NIT Jalandhar, and Ph.D. from the National Institute of Technology (NIT) Warangal. His research interests include visible light communication (VLC), optical OFDM, wireless communications, 5G/6G networks, machine learning for communication systems, vehicular networks, and signal processing. He has authored several research publications in reputed SCI-indexed journals, including IEEE Journal of Lightwave Technology, Optics Communications, Optik, Physical Communication, and AEU. He has filed two Indian patents and two copyrights in the areas of optical wireless communications and signal processing. His current research focuses on AI-enabled resource allocation for V2V networks, deep learning-assisted communication systems, and next-generation intelligent wireless technologies.",
