    description: "Mr. Gundagani Kaushik is an Assistant Professor in the Department of Electronics and Communication Engineering (ECE) at MLR Institute of Technology. He holds an M.Tech degree and has over 6 years and 9 months of teaching experience in engineering education. His areas of interest include VLSI Design, Microwave Engineering, Control Engineering, Speech Synthesis, and Speech Signal Analysis. He is passionate about exploring emerging technologies and their applications in modern communication and intelligent systems.\n\nMr. Kaushik has authored 18 research publications in reputed national and international journals and conferences and holds one patent. He has demonstrated academic excellence by qualifying the GATE examination five times and successfully clearing the NIELIT Scientist Examination. He also serves as the ALS In-Charge for the ECE Department, contributing to academic administration, student development, and the promotion of research-oriented learning among aspiring engineers.",
