    description: "Dr. K. Nishanth Rao is an accomplished academician and researcher serving as an Associate Professor in the Department of Electronics and Communication Engineering (ECE) at MLR Institute of Technology. He holds a B.Tech in ECE, an M.Tech in RF & Microwave Engineering, and earned his Ph.D. in Antennas with IoT applications in 2022. With over 13 years of teaching and research experience, he has been associated with MLRIT since 2014.\n\nHis areas of specialization include Antennas, Electromagnetic Fields, Microwave Engineering, Wireless Communication, and Internet of Things (IoT). Dr. Nishanth Rao has contributed extensively to research through numerous publications in reputed journals, conferences, and book chapters, focusing on antenna design, wireless networks, microwave systems, VLSI technologies, and emerging communication technologies.\n\nAs an educator, he has taught a wide range of subjects including Electromagnetic Theory and Transmission Lines (EMTL), Antennas and Wave Propagation (AWP), Microwave Engineering (MWE), Digital Communications (DC), Computer Networks (CN), and Wireless Communication Networks (WCN). He is actively involved in academic development, mentoring students, guiding research activities, and promoting innovation-driven learning.\n\nDr. Nishanth Rao is committed to advancing engineering education through quality teaching, interdisciplinary research, industry collaboration, and the development of next-generation communication technologies.",
