    description: "Dr. Kiran Chand Ravi is an Associate Professor in the Department of Electronics and Communication Engineering with over 15 years of combined academic and industry experience. He earned his Ph.D. in RF & Microwave Engineering from VIT-AP University in 2023. His research interests include 5G/6G MIMO antennas, RF and microwave circuit design, electromagnetic band gap structures, and advanced communication systems. Dr. Ravi has published several SCI-indexed research papers and holds Indian patents in antenna design and IoT-based biomedical devices. He has presented research at various IEEE international conferences and actively guides undergraduate and postgraduate projects in RF, IoT, and communication technologies. He is a lifetime member of ISTE and IETE and is committed to innovative teaching, research excellence, and technological advancement.",
