    description: "Mrs. Mary Kannidi is an Assistant Professor in the Department of Electronics and Communication Engineering (ECE) at MLR Institute of Technology. She holds a Master of Technology (M.Tech) degree at MLR Institute of Technology and has over two years of teaching experience in engineering education. Her academic interests include Digital Electronics, Digital System Design, and VLSI Design. She has published four research papers in reputed academic forums, reflecting her commitment to continuous learning and professional development. Mrs. Mary has also undergone specialized training in VLSI RTL Design and Verification, enhancing her expertise in modern semiconductor design methodologies. She is dedicated to creating an engaging learning environment that promotes analytical thinking, problem-solving skills, and technical excellence among students. Her focus is on bridging theoretical concepts with practical applications to prepare students for successful careers in the field of electronics and communication engineering.",
