    description: "Dr. P. Yakaiah is an Professor in the Department of Electronics and Communication Engineering (ECE) at MLR Institute of Technology, with over 21 years of teaching and research experience. He earned his Ph.D. from Rayalaseema University in 2024 and holds an M.Tech in Digital Systems and Computer Engineering from Jawaharlal Nehru Technological University Hyderabad. His research interests include digital image processing, computer vision, embedded systems, IoT, wireless communication, and machine learning. Dr. Yakaiah has published several research papers in reputed journals and conferences, covering topics such as image compression, object detection, healthcare monitoring systems, brain tumor detection, and smart safety devices. He is also actively involved in professional development through NPTEL certifications in emerging technologies and engineering education.",
