    description: "Dr. Shrikant Upadhyay is an accomplished academician, researcher, and quality assurance professional with over 15 years of experience in teaching, research, and academic administration. He holds a Ph.D. in Electronics and Communication Engineering with specialization in Digital Signal Processing (Speech) from Jaipur National University, Jaipur in 2019. His research interests include IoT, Artificial Intelligence, Machine Learning, VLSI, Embedded Systems, Smart Healthcare, and Communication Engineering. Dr. Upadhyay has authored more than 50 Scopus-indexed journal and conference publications, including papers in SCI-indexed journals such as Sensors, Electronics, and Computational and Mathematical Methods in Medicine. He is also the author of a book on Microprocessors and Microcontrollers and holds several Indian and international patents. As IQAC Coordinator, he plays a pivotal role in institutional quality assurance, accreditation, outcome-based education implementation, policy formulation, and continuous improvement initiatives. He actively contributes to research, innovation, faculty development, and academic excellence in higher education.",
