    description: "Dr. Y. Sivaramakrishna received the B.Tech degree in Electronics and Communication Engineering, the M.Tech degree in Embedded Systems, and the Ph.D. degree in Electronics and Communication Engineering. He is currently working as an Assistant Professor in the Department of Electronics and Communication Engineering at MLR Institute of Technology, Hyderabad, India. His research interests include speech enhancement, biomedical signal processing, deep learning, artificial intelligence, machine learning, and wireless communication systems. He has published several research articles in reputed international journals and conferences, particularly in the areas of speech processing, healthcare analytics, and intelligent signal processing. He is actively involved in guiding undergraduate and postgraduate projects and contributes to academic research through interdisciplinary collaborations. His current research focuses on explainable AI, attention-based deep learning architectures, and real-time biomedical signal analysis for healthcare applications.",
