    description: "Dr. Vijaya Kumar Velpula is an Assistant Professor in the Department of Electronics and Communication Engineering at MLR Institute of Technology, Hyderabad. He earned his Ph.D. from VIT-AP University in 2023, specializing in Medical Image Processing, with a research focus on automated multi-stage glaucoma detection using machine learning and deep learning techniques. He has over a decade of academic and teaching experience, having served as a lecturer, GATE faculty, and assistant professor at various engineering institutions. His research interests include medical image analysis, machine learning, deep learning, computer vision, and signal processing. Dr. Velpula has published several research articles in reputed SCI-indexed journals and international conferences and holds an Indian patent in glaucoma detection. He is proficient in MATLAB, Python, Verilog HDL, and LaTeX, and actively contributes to research, teaching, and academic development.",
