    description: "Dr. J. Krishnaraj is a Professor in the Department of Mechanical Engineering at MLR Institute of Technology, Hyderabad, with over 26 years of teaching, research, and academic administration experience. He holds a Ph.D. in Manufacturing Engineering from Annamalai University and is a ratified research supervisor under JNTUH. His areas of expertise include Manufacturing Engineering, Thermal Engineering, Renewable Energy Systems, Additive Manufacturing, Robotics, and Industrial Engineering. Dr. Krishnaraj has published numerous research papers in SCI, Scopus, and Web of Science indexed journals and has authored a book on Engineering Graphics. He holds multiple patents and has coordinated several faculty development programs and research initiatives. An Innovation Ambassador certified by the Ministry of Education's Innovation Cell, he actively contributes to research, industry collaboration, outcome-based education, and technology-driven engineering education.",
