    description: "Dr. G. Chandra Mohana Reddy is an Assistant Professor in the Department of Mechanical Engineering at MLR Institute of Technology. He completed his Ph.D. in Mechanical Engineering from GITAM School of Technology, with research focused on the analysis of functionally graded materials and advanced beam theories.\n\nHis research interests include functionally graded beams and plates, thermal and mechanical behavior of advanced composite structures, finite element analysis, buckling, vibration, and bending analysis using higher-order and unified shear deformation theories. He has published research articles in reputed international journals and actively contributes to the fields of computational mechanics and structural analysis.\n\nAs an academician, Dr. Reddy is involved in teaching undergraduate engineering courses such as Design of Machine Elements, Machine Drawing, CAD/CAM, and Finite Element Analysis. He actively participates in curriculum development, outcome-based education (OBE) implementation, NBA accreditation activities, student mentoring, and research supervision.\n\nHis professional objective is to integrate innovative teaching methodologies with advanced research to develop competent engineering graduates and contribute to the advancement of mechanical engineering education and research.",
