    description: "Dr. Harikishor Kumar is currently working as Associate Professor in the Department of Mechanical Engineering. His research interests are mainly focused on the development of composites through  solid state method for mechanical  applications. Dr. Harikishor Kumar is an accomplished Associate Professor in the Department of Mechanical Engineering, where he brings extensive expertise and knowledge to his work. His research interests are centered on fabrication of various new materials. \nAs an expert in his field, Dr. Kumar is highly skilled in the study of materials science and engineering and manufacturing Processes with a focus on the mechanical properties of materials and their un-conventional characterization. His work is characterized by a deep understanding of the fundamental principles governing the behavior of these materials and processes, as well as a practical approach to their design and development. \nDr. Kumar's contributions to the field of mechanical engineering have been widely recognized, both nationally and internationally. His research has been published in numerous top-tier scientific journals, and he has presented his work at conferences and symposia around the world.",
