    books: [],
    description: "I J. Laxmi Prasad, Assistant Professor in Mechanical Engineering Department at MLR Institute of Technology, Hyderabad, has been serving since December 2016. Prior to the academic career, I worked as a Mechanical Design Engineer at Dell International Services Pvt. Ltd., gaining valuable industry experience in mechanical design and engineering solutions. With over nine years of teaching experience, dedicated to nurturing student innovation and technical expertise in the field of mechanical engineering.\n\nMy professional journey spans both industry and academia, allowing to bridge practical engineering applications with theoretical education. I actively contribute to curriculum development, student mentoring, and technical workshops, preparing future engineers for careers in technology-driven industries. Dual background in corporate mechanical design and academic instruction equips him to guide students through real-world engineering challenges while fostering creativity and problem-solving skills in the classroom.",
