    books: [],
    description: "Moyya Sundeep\nAssistant Professor, Mechanical Engineering | Industrial Automation & AI Innovator\n\nMoyya Sundeep is an accomplished engineering professional and educator with a unique career spanning heavy industry operations, academic research, and cutting-edge tech innovation. He currently serves as an Assistant Professor in Mechanical Engineering, a role he has held since June 2018. Alongside his teaching responsibilities, he serves as the campus Cultural Coordinator, leading student engagement and organizing large-scale university events.\n\nPrior to entering academia, Sundeep spent over four years (2014–2018) as a Mechanical Engineer in Distributed Control System (DCS) Operations for the Power Plant Division at Vandana Global Pvt. Ltd. in Raipur, Chhattisgarh. There, he managed critical, high-capacity infrastructure, including 33MW and 8MW turbines, 30tph and 55tph Waste Heat Recovery Boilers (WHRB), and twin 90tph Atmospheric Fluidized Bed Combustion (AFBC) boilers, while successfully resolving complex shutdown maintenance problems.\n\nAn active researcher and innovator, Sundeep has contributed to 21 research publications and holds two patents. Bridging the gap between traditional mechanical engineering and modern artificial intelligence, he was awarded the Best Mentor and Best Project awards at ICTIEE 2026 (GITAM University, Bengaluru) for developing VISION AID—an AI-powered, real-time object recognition system designed to assist the visually impaired. Driven by a passion for mentoring, his work continues to focus on applying smart technologies to solve real-world problems.\n\n\n\n( if it is compulsory to be in 150 words only )\n\n\n\nMoyya Sundeep\nAssistant Professor, Mechanical Engineering | AI & Automation Innovator\n\nMoyya Sundeep is an accomplished educator, researcher, and former industrial engineer who bridges the gap between traditional mechanical systems and modern AI innovation. Currently serving as an Assistant Professor in Mechanical Engineering since 2018, he also drives campus student life as the institutional Cultural Coordinator.\n\nSundeep's professional foundation includes over four years as a DCS Operations Mechanical Engineer at Vandana Global Pvt. Ltd., where he managed high-capacity turbines, WHRB/AFBC boilers, and complex shutdown maintenance. Transitioning to academia, he has become a prolific innovator, contributing to 21 research publications and securing two patents. Notably, his work at the intersection of tech and empathy earned him the Best Mentor and Best Project awards at ICTIEE 2026 for developing VISION AID—an AI-powered, real-time object recognition system for the visually impaired.",
