    description: "Dr. Ch. Ravikiran is an accomplished academician, researcher, and Associate Professor in the Department of Mechanical Engineering at MLR Institute of Technology, Hyderabad, with over 12 years of teaching and research experience. He holds a Ph.D. in Internal Combustion Engines, along with M.Tech. and B.Tech. degrees in Mechanical Engineering. His research interests include thermal engineering, alternative fuels, internal combustion engines, advanced manufacturing, composite materials, and machine learning applications in engineering. Dr. Ravikiran has authored multiple textbooks, published numerous research papers in SCI, SCIE, Scopus-indexed, and international journals, and holds several patents in areas such as agricultural robotics, renewable energy, and thermal systems. He is an active member of professional bodies including AMIE and SAEINDIA and has contributed extensively to academic development through conferences, faculty development programs, and research collaborations.",
