    description: "Dr. A. Vivek Anand is the Dean – Planning and Development, NIRF Nodal Officer, and Professor in the Department of Aeronautical Engineering at MLR Institute of Technology (MLRIT), Hyderabad, India. He earned his Ph.D. in Aerospace Engineering from Madras Institute of Technology (MIT), Anna University, Chennai. His research interests include Surface Engineering, Fluid-Structure Interaction, Advanced Materials and Composites, Corrosion Engineering, Sustainable Energy Systems, and Machine Learning Applications in Engineering.\n\nDr. Vivek Anand has authored more than 30 publications in reputed SCIE, Scopus, and ESCI-indexed journals and conferences and has contributed to several book chapters. He has successfully secured and managed research and development projects funded by MSME, DRDO, and AICTE. As NIRF Nodal Officer, he has played a key role in advancing institutional ranking initiatives and strategic development, contributing to MLRIT's recognition in the NIRF Engineering rankings. He established the Intellectual Property Facilitation Centre (IPFC) at MLRIT and has led several innovation, research, and technology commercialization initiatives.",
