    books: [],
    description: "Ms. G. Sravanthi is an Assistant Professor in the Department of Aeronautical Engineering with over 7 years of teaching experience. She holds a B.Tech in Aeronautical Engineering and an M.Tech in Aerospace Engineering, specializing in structures. Her research interests include composite materials, aircraft fuselage analysis, UAV optimization, and thermal systems. She has published 11 international papers in Scopus-indexed venues such as the Journal of Physics: Conference Series, AIP Conference Proceedings, Materials Today: Proceedings, and E3S Web of Conferences. She has two published patents: a weed-identifying rover and a morphing wing for UAV. Currently, she is working on a consultancy project on fluid flow analysis of landing gear structures with a sanctioned amount of Rs. 2,00,000. She has coordinated internship programs, attended multiple AICTE-ATAL workshops on UAVs and AI tools, and completed NPTEL courses on accreditation and outcome-based learning. She is an Associate Member of the Institute of Aeronautics, Astronautics & Aviation (IAAA).",
