    description: "10 years of teaching experience and is actively involved in teaching emerging and interdisciplinary subjects such as Artificial Intelligence for Aerodynamics, IoT-Based Drone Systems, Machine Learning, Python Programming, Aerospace Propulsion, Engineering Graphics, Jets & Rockets, and Finite Element Methods. \nResearch interests span UAV design, aerodynamics, composite materials, aerospace structures, additive manufacturing, machine learning applications, and advanced manufacturing technologies. He has authored and co-authored numerous research papers published in reputed journals and conference proceedings, covering areas such as propeller design, micro air vehicles, aircraft structures, composite materials, and optimization techniques and significant contributions to innovation through multiple Indian patent publications, including inventions related to UAV systems, morphing wings, composite materials, and aerospace mechanisms. He is also the recipient of a copyright for work on vibration frequency distribution analysis of cantilever beams.\nCommitted to academic excellence and outcome-based education, he has completed several professional certifications from NPTEL, IIT Kharagpur, NITTTR Chennai, and IUCEE in areas such as Machine Learning, Internet of Things, Industry 4.0, Accreditation, and Engineering Education. He is an Educational Member of the American Institute of Aeronautics and Astronautics (AIAA) and actively contributes to research, consultancy, curriculum development, and student project mentoring.",
