    description: "Dr. Jostna Kumar Gantepogu is an Assistant Professor in the Department of Management Studies at Malla Reddy Institute of Technology and Research (MLRIT). He is a researcher and management educator specializing in Human Resource Management, Organizational Behavior, Talent Management, Performance Management, and AI-driven Management Education. He has qualified UGC-NET JRF (Management Studies), UGC-NET (Lectureship), and APSET (Management Studies). He also holds a PG Diploma in Industrial Psychology and a PG Diploma in Industrial Relations and Labour Laws from Pondicherry University.\n\nA committed lifelong learner, Dr. Jostna Kumar Gantepogu has earned prestigious NPTEL recognitions, including the STAR Enthusiast Award, Motivated Learner Award, and Star Discipline Award. He has actively contributed to teaching, research, curriculum development, faculty development, and student mentoring. His research focuses on HRM, Talent Management, Employee Performance Evaluation, Organizational Development, and Artificial Intelligence applications in management education. He is also recognized as a STAR Faculty of TLC, MLRIT, promoting outcome-based and technology-enabled learning.",
