    description: "Dr. T. Shanmugapriya is an Associate Professor at MLR Institute of Technology, Hyderabad, with over 17 years of experience in management education, research, and academic administration. She holds a Ph.D. in Management with a specialization in Human Resource Management. She has published more than 21 research papers in national and international conferences and authored six books covering Human Resource Management, Organizational Behavior, Customer Relationship Management, Financial Management, Digital Women Entrepreneurship, and Marketing Research.\n\nShe serves as an editorial board member of international journals and has held key leadership positions, including Convener of the Institution Innovation Council (IIC), NPTEL SPOC, and Chairman of the Board of Studies for MBA. Dr. Shanmugapriya has organized over 100 academic and professional development programs, including FDPs, guest lectures, entrepreneurship initiatives, and AICTE-sponsored events. Her contributions to academic excellence, innovation, quality assurance, and institutional development reflect her commitment to advancing higher education.",
