    description: "Dr. Atasi Ray is an Assistant Professor of Physics at MLR Institute of Technology, Hyderabad. She earned her Ph.D. in Physics from the University of Hyderabad, where her research focused on Flavor Physics and the search for physics beyond the Standard Model. Her research contributions include several publications in reputed international journals and conference proceedings in the fields of particle and high-energy physics.\n\nWith a strong passion for teaching and mentoring, Dr. Ray has been actively involved in undergraduate engineering education, teaching Applied Physics and Engineering Physics with consistently excellent academic outcomes. Her academic interests span particle physics, quantum mechanics, and innovative pedagogical approaches in physics education. She is committed to fostering scientific curiosity, critical thinking, and research aptitude among students while contributing to advancements in physics through scholarly research and academic engagement.",
