export function getFacultyBySlug(slug: string): FacultyProfile | undefined {
  return FACULTY.find((f) => f.slug === slug);
}

export function getFacultyByDepartment(department: string): FacultyProfile[] {
  return FACULTY.filter((f) => f.department === department);
}

export function getAllFacultySlugs(): string[] {
  return FACULTY.map((f) => f.slug);
}
